export type ParsedPlaceSellInstruction<
  TProgram extends string = typeof OUTCOME_TOKENS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    user: TAccountMetas[0];
    /** Funds the order and its escrow, and gets that rent back when they close. */
    payer: TAccountMetas[1];
    config: TAccountMetas[2];
    /** Exists only for a wallet the registrar has registered. */
    trader: TAccountMetas[3];
    market: TAccountMetas[4];
    order: TAccountMetas[5];
    escrow: TAccountMetas[6];
    /**
     * Any token account of the user for the outcome mint; it need not be the associated
     * one.
     */
    userOutcome: TAccountMetas[7];
    outcomeMint: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
  };
  data: PlaceSellInstructionData;
};

export function parsePlaceSellInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedPlaceSellInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      user: getNextAccount(),
      payer: getNextAccount(),
      config: getNextAccount(),
      trader: getNextAccount(),
      market: getNextAccount(),
      order: getNextAccount(),
      escrow: getNextAccount(),
      userOutcome: getNextAccount(),
      outcomeMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getPlaceSellInstructionDataDecoder().decode(instruction.data),
  };
}
